/**
 * The document shell: <head> (SEO, Open Graph, icons, fonts), header, footer,
 * floating WhatsApp button and scripts.
 */
import { FACEBOOK_PLACEHOLDER } from '../lib/content.mjs';
import { esc, jsonLd } from '../lib/util.mjs';
import { waButton } from './components.mjs';

const GENERATED_NOTE =
  '<!-- Generated by scripts/build.mjs from the files in /content. Edit the content files, then run "npm run build". -->';

/* ------------------------------------------------------------------ */
/* Structured data                                                     */
/* ------------------------------------------------------------------ */
function organization(ctx) {
  const { site } = ctx;
  const fb = (site.social?.facebook || '').trim();
  return {
    '@type': 'Organization',
    '@id': site.url ? `${site.url}/#organization` : undefined,
    name: site.brand.shortName,
    alternateName: site.brand.name,
    description: site.brand.description,
    url: site.url || undefined,
    logo: site.url ? `${site.url}/${site.brand.logoPng}` : undefined,
    email: site.contact.email,
    telephone: `+${site.contact.whatsapp.number}`,
    contactPoint: [
      {
        '@type': 'ContactPoint',
        contactType: 'customer support',
        email: site.contact.email,
        telephone: `+${site.contact.whatsapp.number}`,
        availableLanguage: ['English'],
      },
    ],
    sameAs: fb && fb !== FACEBOOK_PLACEHOLDER ? [fb] : undefined,
  };
}

export function faqSchema(ctx) {
  const { c } = ctx;
  return {
    '@type': 'FAQPage',
    mainEntity: c.faq.map((x) => ({
      '@type': 'Question',
      name: c.fill(x.q),
      acceptedAnswer: { '@type': 'Answer', text: c.fill(x.a) },
    })),
  };
}

export function breadcrumbSchema(ctx, items) {
  if (!ctx.site.url) return null;
  return {
    '@type': 'BreadcrumbList',
    itemListElement: items.map((it, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      name: it.name,
      item: `${ctx.site.url}/${it.path === 'index.html' ? '' : it.path}`,
    })),
  };
}

function graph(ctx, extra) {
  const { site } = ctx;
  const nodes = [organization(ctx)];
  if (site.url) {
    nodes.push({
      '@type': 'WebSite',
      '@id': `${site.url}/#website`,
      url: `${site.url}/`,
      name: site.brand.shortName,
      publisher: { '@id': `${site.url}/#organization` },
    });
  }
  for (const e of extra) if (e) nodes.push(e);
  return { '@context': 'https://schema.org', '@graph': nodes };
}

/* ------------------------------------------------------------------ */
/* Header                                                              */
/* ------------------------------------------------------------------ */
function header(ctx) {
  const { site } = ctx;
  const wa = site.contact.whatsapp;
  const nav = site.nav
    .map((n) => {
      const current = n.page === ctx.page;
      return `<li><a class="nav__link${current ? ' is-current' : ''}" href="${ctx.href(n.page)}"${current ? ' aria-current="page"' : ''}>${esc(n.label)}</a></li>`;
    })
    .join('');
  return `
<a class="skip-link" href="#main">Skip to main content</a>
<header class="site-header" id="site-header">
  <div class="topbar">
    <div class="container topbar__inner">
      <p class="topbar__tagline">${esc(site.brand.tagline)}</p>
      <ul class="topbar__links">
        <li><a href="${esc(ctx.mailto())}">${ctx.icon('mail')}<span>${esc(site.contact.email)}</span></a></li>
        <li><a href="${esc(ctx.wa())}" target="_blank" rel="noopener noreferrer" data-wa="topbar">${ctx.icon('whatsapp')}<span>WhatsApp: ${esc(wa.display)}</span></a></li>
      </ul>
    </div>
  </div>
  <div class="container header__inner">
    <a class="brand" href="${ctx.href('home')}" aria-label="${esc(site.brand.shortName)} — home">
      <img class="brand__logo" src="${ctx.asset(site.brand.logo)}" width="${ctx.size(site.brand.logo).width}" height="${ctx.size(site.brand.logo).height}" alt="" decoding="async">
      <span class="brand__text"><span class="brand__name">ACHIEVE</span><span class="brand__sub">ABOARD</span></span>
    </a>
    <nav class="nav" id="site-nav" aria-label="Main">
      <ul class="nav__list">${nav}</ul>
      <div class="nav__cta">
        ${waButton(ctx, { label: 'Chat on WhatsApp', loc: 'mobile-menu', size: 'lg', block: true })}
        <a class="nav__mail" href="${esc(ctx.mailto())}">${ctx.icon('mail')}<span>${esc(site.contact.email)}</span></a>
      </div>
    </nav>
    <div class="header__actions">
      <a class="btn btn--wa btn--sm header__cta" href="${esc(ctx.wa())}" target="_blank" rel="noopener noreferrer" data-wa="header">${ctx.icon('whatsapp')}<span>${esc(site.headerCta)}</span><span class="sr-only"> (opens WhatsApp in a new tab)</span></a>
      <button class="nav-toggle" type="button" aria-expanded="false" aria-controls="site-nav" aria-label="Open menu">
        <span class="nav-toggle__open">${ctx.icon('menu')}</span>
        <span class="nav-toggle__close">${ctx.icon('close')}</span>
      </button>
    </div>
  </div>
</header>`;
}

/* ------------------------------------------------------------------ */
/* Footer                                                              */
/* ------------------------------------------------------------------ */
function footer(ctx) {
  const { site } = ctx;
  const wa = site.contact.whatsapp;
  const fb = (site.social?.facebook || '').trim();
  const links = site.footerLinks
    .map((n) => `<li><a href="${ctx.href(n.page)}">${esc(n.label)}</a></li>`)
    .join('');
  const year = new Date().getFullYear();
  return `
<footer class="site-footer">
  <div class="container footer__grid">
    <div class="footer__brand">
      <a class="footer__logo" href="${ctx.href('home')}" aria-label="${esc(site.brand.shortName)} — home">
        <img src="${ctx.asset(site.brand.logo)}" width="88" height="88" alt="" loading="lazy" decoding="async">
      </a>
      <p class="footer__name">${esc(site.brand.name)}</p>
      <p class="footer__tagline">${esc(site.brand.tagline)}</p>
      <p class="footer__about">${esc(site.brand.description)}</p>
      ${
        fb
          ? `<a class="footer__social" href="${esc(fb)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(site.brand.shortName)} on Facebook (opens in a new tab)" data-wa="facebook-footer">${ctx.icon('facebook')}</a>`
          : ''
      }
    </div>
    <nav class="footer__col" aria-label="Quick links">
      <h2 class="footer__heading">Quick Links</h2>
      <ul class="footer__list">${links}</ul>
    </nav>
    <div class="footer__col">
      <h2 class="footer__heading">Contact</h2>
      <ul class="footer__list footer__list--contact">
        <li><a href="${esc(ctx.mailto())}">${ctx.icon('mail')}<span>${esc(site.contact.email)}</span></a></li>
        <li><a href="${esc(ctx.wa())}" target="_blank" rel="noopener noreferrer" data-wa="footer">${ctx.icon('whatsapp')}<span>WhatsApp: ${esc(wa.display)}</span></a></li>
      </ul>
      ${waButton(ctx, { label: 'Chat on WhatsApp', loc: 'footer-button', cls: 'footer__btn' })}
    </div>
  </div>
  <div class="footer__bottom">
    <div class="container footer__bottom-inner">
      <p>© <span data-year>${year}</span> ${esc(site.brand.name)}. All rights reserved.</p>
      <p class="footer__legal"><a href="${ctx.href('privacy')}">Privacy Policy</a></p>
      <p class="footer__disclaimer">${esc(site.disclaimer)}</p>
    </div>
  </div>
</footer>`;
}

function floatingWhatsApp(ctx) {
  return `
<a class="wa-float" href="${esc(ctx.wa())}" target="_blank" rel="noopener noreferrer" data-wa="floating" aria-label="Chat with ${esc(ctx.site.brand.shortName)} on WhatsApp (opens in a new tab)">
  <span class="wa-float__icon">${ctx.icon('whatsapp')}</span>
  <span class="wa-float__label">Chat on WhatsApp</span>
</a>`;
}

/* ------------------------------------------------------------------ */
/* Analytics (only when IDs are set in content/site.js)                */
/* ------------------------------------------------------------------ */
function analytics(site) {
  const out = [];
  const px = site.analytics?.metaPixelId;
  const ga = site.analytics?.googleAnalyticsId;
  if (px && /^\d{5,20}$/.test(px)) {
    out.push(
      `<script>!function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,document,'script','https://connect.facebook.net/en_US/fbevents.js');fbq('init','${px}');fbq('track','PageView');</script>`,
    );
  }
  if (ga && /^(G|AW)-[A-Z0-9]{4,14}$/i.test(ga)) {
    out.push(
      `<script async src="https://www.googletagmanager.com/gtag/js?id=${ga}"></script>`,
      `<script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag('js',new Date());gtag('config','${ga}');</script>`,
    );
  }
  return out.join('\n');
}

/* ------------------------------------------------------------------ */
/* Full document                                                       */
/* ------------------------------------------------------------------ */
export function renderDocument(
  ctx,
  { title, description, main, schema = [], preload = '', type = 'website', article = null, noindex = false },
) {
  const { site } = ctx;
  const pagePath = ctx.file;
  const canonical = site.url ? `${site.url}/${pagePath === 'index.html' ? '' : pagePath}` : '';
  const ogImageExists = ctx.exists(site.seo.ogImage);
  const ogImage = ogImageExists ? ctx.abs(site.seo.ogImage) : '';

  // Render header/footer/float first so every icon they use is registered, then build the sprite.
  const headerHtml = header(ctx);
  const footerHtml = footer(ctx);
  const floatHtml = floatingWhatsApp(ctx);
  const sprite = ctx.sprite();

  const head = [
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">',
    `<title>${esc(title)}</title>`,
    `<meta name="description" content="${esc(description)}">`,
    `<meta name="robots" content="${noindex ? 'noindex, follow' : 'index, follow, max-image-preview:large'}">`,
    canonical ? `<link rel="canonical" href="${esc(canonical)}">` : '',
    `<meta name="theme-color" content="${esc(site.seo.themeColor)}">`,
    '<meta name="format-detection" content="telephone=no">',
    // Open Graph / Facebook
    `<meta property="og:type" content="${type}">`,
    `<meta property="og:site_name" content="${esc(site.brand.shortName)}">`,
    `<meta property="og:locale" content="${esc(site.seo.locale)}">`,
    `<meta property="og:title" content="${esc(title)}">`,
    `<meta property="og:description" content="${esc(description)}">`,
    canonical ? `<meta property="og:url" content="${esc(canonical)}">` : '',
    ogImage ? `<meta property="og:image" content="${esc(ogImage)}">` : '',
    ogImage ? '<meta property="og:image:type" content="image/jpeg">' : '',
    ogImage ? '<meta property="og:image:width" content="1200">' : '',
    ogImage ? '<meta property="og:image:height" content="630">' : '',
    ogImage ? `<meta property="og:image:alt" content="${esc(site.seo.ogImageAlt)}">` : '',
    article ? `<meta property="article:published_time" content="${esc(article.date)}">` : '',
    article ? `<meta property="article:section" content="${esc(article.category)}">` : '',
    // Twitter / X (also used by several messengers)
    `<meta name="twitter:card" content="${ogImage ? 'summary_large_image' : 'summary'}">`,
    `<meta name="twitter:title" content="${esc(title)}">`,
    `<meta name="twitter:description" content="${esc(description)}">`,
    ogImage ? `<meta name="twitter:image" content="${esc(ogImage)}">` : '',
    // Icons + manifest
    `<link rel="icon" href="${ctx.asset('favicon.ico')}" sizes="48x48">`,
    `<link rel="icon" href="${ctx.asset('assets/img/icons/favicon.svg')}" type="image/svg+xml">`,
    `<link rel="icon" href="${ctx.asset('assets/img/icons/favicon-32.png')}" type="image/png" sizes="32x32">`,
    `<link rel="apple-touch-icon" href="${ctx.asset('assets/img/icons/apple-touch-icon.png')}">`,
    `<link rel="manifest" href="${ctx.asset('site.webmanifest')}">`,
    // Fonts (self-hosted) + critical image
    `<link rel="preload" href="${ctx.asset('assets/fonts/figtree-var.woff2')}" as="font" type="font/woff2" crossorigin>`,
    `<link rel="preload" href="${ctx.asset('assets/fonts/fraunces-var.woff2')}" as="font" type="font/woff2" crossorigin>`,
    preload,
    // "js" enables scroll-reveal styling. If main.js has not loaded after 6 s, switch it off so nothing stays hidden.
    '<script>document.documentElement.classList.add("js");setTimeout(function(){window.aaReady||document.documentElement.classList.remove("js")},6000)</script>',
    `<link rel="stylesheet" href="${ctx.versioned('assets/css/styles.css')}">`,
    `<script src="${ctx.versioned('assets/js/main.js')}" defer></script>`,
    `<script type="application/ld+json">${jsonLd(graph(ctx, schema))}</script>`,
    analytics(site),
  ]
    .filter(Boolean)
    .join('\n');

  return `<!doctype html>
${GENERATED_NOTE}
<html lang="en">
<head>
${head}
</head>
<body data-page="${esc(ctx.page)}">
${sprite}
${headerHtml}
<main id="main" tabindex="-1">
${main}
</main>
${footerHtml}
${floatHtml}
</body>
</html>
`;
}

/* ------------------------------------------------------------------ */
/* 404 page (self-contained, uses root-relative URLs because it can be */
/* served from any path)                                               */
/* ------------------------------------------------------------------ */
export function render404(ctx) {
  const { site } = ctx;
  const home = site.url ? `${site.url}/` : '/';
  const rel = (p) => (site.url ? `${site.url}/${p}` : `/${p}`);
  return `<!doctype html>
${GENERATED_NOTE}
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Page not found | ${esc(site.brand.shortName)}</title>
<meta name="robots" content="noindex">
<meta name="theme-color" content="${esc(site.seo.themeColor)}">
<link rel="icon" href="${rel('assets/img/icons/favicon.svg')}" type="image/svg+xml">
<link rel="icon" href="${rel('favicon.ico')}" sizes="48x48">
<style>
  body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;background:#f4f7fd;color:#0b1d4a;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;text-align:center}
  main{max-width:30rem}
  img{width:96px;height:96px;margin-bottom:8px}
  h1{font-size:clamp(1.75rem,6vw,2.5rem);line-height:1.15;margin:.25em 0}
  p{color:#3b4a6b;line-height:1.6;margin:.5em 0 1.5em}
  .row{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
  a.b{display:inline-flex;align-items:center;min-height:48px;padding:0 22px;border-radius:999px;font-weight:700;text-decoration:none}
  a.p{background:#25d366;color:#04210f}
  a.s{border:2px solid #0b1d4a;color:#0b1d4a}
</style>
</head>
<body>
<main>
  <img src="${rel(site.brand.logo)}" alt="${esc(site.brand.shortName)}" width="96" height="96">
  <h1>We couldn’t find that page</h1>
  <p>The link may be old or mistyped. Head back to the homepage, or message us on WhatsApp and we’ll point you in the right direction.</p>
  <div class="row">
    <a class="b p" href="${esc(ctx.wa())}" target="_blank" rel="noopener noreferrer">Chat on WhatsApp</a>
    <a class="b s" href="${esc(home)}">Back to homepage</a>
  </div>
</main>
</body>
</html>
`;
}
